pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, IERC1271} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    SigWallet wallet;
    Tok token;
    uint256 constant T0 = 1_000_000;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        wallet = new SigWallet();
        token = new Tok();
        vm.warp(T0);
    }

    function testFuzz_property(
        uint256 duration,
        uint256 premium,
        uint256 strike,
        uint256 expiration,
        uint256 nonce
    ) public {
        duration = bound(duration, 1, 10_000 days - 1);
        premium = bound(premium, 1, 1e30);
        strike = bound(strike, 0, 1e30);
        expiration = bound(expiration, T0 + 1, T0 + 3650 days);
        nonce = bound(nonce, 0, type(uint128).max);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(wallet),
            isCall: false,
            isLong: true,
            baseAsset: address(token),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory sig = new bytes(65);
        uint256[] memory floors = new uint256[](0);

        bool ok;
        try c.fillOrder(order, sig, floors) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok, "fillOrder should succeed");
        bytes32 orderHash = c.hashOrder(order);
        assertTrue(
            c.positionExpirations(uint256(orderHash)) == T0 + duration,
            "long position expiration must be set to fill time + duration"
        );
    }
}

